options.onClick:
var singlar = this.getFormRef().globalDsv.signalR;

//取消监听
singlar.off("PublicLogMessage");

//监听事件
singlar.on("PublicLogMessage", (para, msg) => {
  //debugger;
  let table=this.getWidgetRef('dtBusiness',false);
  let tabledataArray = table.getTableData();
  table.setTableData();

  var logLevel = 'warning';
	var logType = '警告'
	if(para.logLevel == 4)
	{
	  logLevel = 'danger';
		logType = '错误';
	}

  const readAlarmDatas = localStorage.getItem('alarmDatas');

  if (readAlarmDatas) {
		   var alarmDatas  = JSON.parse(readAlarmDatas);
		   var newmessage = {
		     logName:para.logName,
	     	    date: para.logDateTime,
    				message: para.message,
    				status: logLevel,
    				type: logType,
				    logLevel:para.logLevel
			 };

			var newDatas =  alarmDatas.filter((item) => item.message !== para.message);

			newDatas.splice(0,0,newmessage);
			newDatas = newDatas.slice(0,500);
			// 存储数据
			localStorage.setItem('alarmDatas', JSON.stringify(newDatas));

			table.setTableData(newDatas);
		}
		else
		{
			var createmessage = [{
			  logName:para.logName,
	     	    date: para.logDateTime,
    				message: para.message,
    				status: logLevel,
    				type: logType,
				    logLevel:para.logLevel
			}];
			// 存储数据
			localStorage.setItem('alarmDatas', JSON.stringify(createmessage));
			alarmDatas = createmessage;
			table.setTableData(alarmDatas);
		}
});

tableColumns.render:
let {row, column} = params
let cellValue = row[column.prop]
let items=[{des:'Trace',type:''},
{des:'Debug',type:''},
{des:'Information',type:''},
{des:'警告',type:'warning'},
{des:'错误',type:'error'},
{des:'Critical',type:''},
{des:'None',type:''}
]
var targetItem=items[parseInt(cellValue)]

let effect='Plain';

return h(components.ElTag, {
 modelValue: cellValue,
 type:targetItem.type,
 effect:effect,
},{default:()=>targetItem.des}
)

